import React, { useEffect } from "react";
import { type HeadFC, navigate, PageProps } from "gatsby";

type RedirectContext = {
  toPath: string;
};

const RedirectPage: React.FC<PageProps<unknown, RedirectContext>> = ({
  pageContext,
}) => {
  const toPath = pageContext?.toPath || "/";

  useEffect(() => {
    if (typeof window !== "undefined") {
      navigate(toPath, { replace: true });
    }
  }, [toPath]);

  return (
    <>
      <main style={{ padding: "2rem", textAlign: "center" }}>
        <p>Redirecting…</p>
        <p>
          If you are not redirected,{" "}
          <a href={toPath}>click here</a>.
        </p>
      </main>
    </>
  );
};

export const Head: HeadFC<unknown, RedirectContext> = ({ pageContext }) => {
  const toPath = pageContext?.toPath || "/";

  return (
    <>
      <meta httpEquiv="refresh" content={`0; url=${toPath}`} />
      <meta name="robots" content="noindex, nofollow" />
    </>
  );
};

export default RedirectPage;
